//! Byte classification/conversion that mirrors the C locale `<cctype>` functions.
//!
//! The C++ original works on `std::string`, i.e. on raw bytes, and runs under the
//! default "C" locale. There `toupper`/`tolower` only touch `a-z`/`A-Z` and every
//! byte >= 0x80 is left alone and is never considered alphanumeric. Reproducing
//! that byte-for-byte matters: inputs such as "Ünï" must survive `upcase` as
//! "ÜNï" and must lose their non-ASCII bytes in `parameterize`.

/// `std::isupper` in the C locale.
pub fn is_upper(b: u8) -> bool {
    b.is_ascii_uppercase()
}

/// `std::isalnum` in the C locale.
pub fn is_alnum(b: u8) -> bool {
    b.is_ascii_alphanumeric()
}

/// `std::toupper` in the C locale.
pub fn to_upper(b: u8) -> u8 {
    b.to_ascii_uppercase()
}

/// `std::tolower` in the C locale.
pub fn to_lower(b: u8) -> u8 {
    b.to_ascii_lowercase()
}

/// True when `haystack` ends with `needle` (byte comparison, case sensitive).
pub fn ends_with(haystack: &[u8], needle: &[u8]) -> bool {
    haystack.len() >= needle.len() && &haystack[haystack.len() - needle.len()..] == needle
}

/// `s.substr(0, n)` clamped the way the callers already guarantee.
pub fn head(s: &[u8], n: usize) -> Vec<u8> {
    s[..n.min(s.len())].to_vec()
}

/// Concatenate a prefix slice with a literal tail.
pub fn joined(prefix: &[u8], tail: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(prefix.len() + tail.len());
    out.extend_from_slice(prefix);
    out.extend_from_slice(tail);
    out
}

