//! Number-agnostic word list shared by `pluralize` and `singularize`.
//!
//! The C++ library carries the classic Rails default set of uncountable nouns.
//! The lookup is an exact, case sensitive comparison of the whole string, which
//! is why "fish" is uncountable but "Fish", "FISH" and "goldfish" are not.

pub const UNCOUNTABLE: [&[u8]; 10] = [
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLE.iter().any(|&u| u == word)
}

