    if ends_with(word, b"ses") {
        // A regex picks the leftmost match, which here is the longest stem:
        // "parentheses" resolves through "parenthe", never through "the".
        let mut best: Option<&[u8]> = None;
        for stem in SIS_STEMS {
            let mut pattern = stem.to_vec();
            pattern.extend_from_slice(b"ses");
            if ends_with(word, &pattern) && best.map_or(true, |b| stem.len() > b.len()) {
                best = Some(stem);
            }
        }
        if let Some(stem) = best {
            let mut out = head(word, n - 3 - stem.len());
            out.extend_from_slice(stem);
            out.extend_from_slice(sis_inner_group(stem));
            out.extend_from_slice(b"sis");
            return out;
        }
    }

    // ([^f])ves$ -> \1fe   ("wolves" -> "wolfe", not "wolf")
    if n >= 4 && ends_with(word, b"ves") && word[n - 4] != b'f' {
        return joined(&word[..n - 3], b"fe");
    }

    // ([^aeiouy]|qu)ies$ -> \1y
    if n >= 4 && ends_with(word, b"ies") {
        let prev = word[n - 4];
        let qu = prev == b'u' && n >= 5 && word[n - 5] == b'q';
        if !is_vowel_or_y(prev) || qu {
            return joined(&word[..n - 3], b"y");
        }
    }

    // (m|l)ice$ -> \1ouse   (not anchored: "slice" -> "slouse")
    if n >= 4 && ends_with(word, b"ice") && (word[n - 4] == b'm' || word[n - 4] == b'l') {
        return joined(&word[..n - 3], b"ouse");
    }

    // (bus)es$ -> \1
    if ends_with(word, b"buses") {
        return head(word, n - 2);
    }

    // (o)es$ -> \1
    if ends_with(word, b"oes") {
        return head(word, n - 2);
    }

    // (cris|ax|test)es$ -> \1is   (must precede the `(x|ch|ss|sh)es` rule,
    // otherwise "axes" would collapse to "ax" instead of "axis")
    if ends_with(word, b"crises") || ends_with(word, b"axes") || ends_with(word, b"testes") {
        return joined(&word[..n - 2], b"is");
    }

    // (octop|vir)i$ -> \1us
    if ends_with(word, b"octopi") || ends_with(word, b"viri") {
        return joined(&word[..n - 1], b"us");
    }

    // (alias|status)es$ -> \1
    if ends_with(word, b"aliases") || ends_with(word, b"statuses") {
        return head(word, n - 2);
    }

    // ^(ox)en$ -> \1   (anchored at both ends: "oxens" and "moxen" are untouched)
    if word == b"oxen" {
        return b"ox".to_vec();
    }

    // (vert|ind)ices$ -> \1ex
    if ends_with(word, b"vertices") || ends_with(word, b"indices") {
        return joined(&word[..n - 4], b"ex");
    }

    // (matr)ices$ -> \1ix
    if ends_with(word, b"matrices") {
        return joined(&word[..n - 4], b"ix");
    }

    // (quiz)zes$ -> \1
    if ends_with(word, b"quizzes") {
        return head(word, n - 3);
    }

    // (x|ch|ss|sh)es$ -> \1
    if ends_with(word, b"xes")
        || ends_with(word, b"ches")
        || ends_with(word, b"sses")
        || ends_with(word, b"shes")
    {
        return head(word, n - 2);
    }

    // s$ -> ''
    if ends_with(word, b"s") {
        return head(word, n - 1);
    }

    word.to_vec()
}

/// A word counts as plural exactly when singularising it changes it. Uncountable
/// nouns and irregulars the rule list does not cover ("children", "men",
/// "people", "geese") therefore report as singular.
pub fn is_plural(word: &[u8]) -> bool {
    singularize(word) != word
}

pub fn is_singular(word: &[u8]) -> bool {
    !is_plural(word)
}

