//! Identifier and label transformations.

use crate::ascii::{is_alnum, is_upper, to_lower, to_upper};
use crate::case::capitalize;
use crate::number::{pluralize, singularize};

/// `camelize(word)` — the C++ default, which keeps the first byte as it is.
///
/// Underscores are dropped and upper case the byte that follows them, so
/// "hello_world" becomes "helloWorld" while an already camel cased
/// "HelloWorld" is returned unchanged.
pub fn camelize(word: &[u8]) -> Vec<u8> {
    camelize_with(word, true)
}

/// `camelize(word, lower_first)`. With `lower_first == false` the first byte of
/// the result is additionally upper cased, which is how `classify` builds its
/// class-style names.
pub fn camelize_with(word: &[u8], lower_first: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut capitalize_next = false;
    for &b in word {
        if b == b'_' {
            capitalize_next = true;
        } else if capitalize_next {
            out.push(to_upper(b));
            capitalize_next = false;
        } else {
            out.push(b);
        }
    }
    if !lower_first {
        if let Some(first) = out.first_mut() {
            *first = to_upper(*first);
        }
    }
    out
}

/// Inserts an underscore before every upper case byte except a leading one, then
/// lower cases everything: "HelloWorld" -> "hello_world", "ADMIN" -> "a_d_m_i_n".
/// Existing underscores, dashes and spaces are preserved verbatim.
pub fn underscore(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for (i, &b) in word.iter().enumerate() {
        if is_upper(b) && i > 0 {
            out.push(b'_');
        }
        out.push(to_lower(b));
    }
    out
}

/// Replaces every underscore with a dash and changes nothing else.
pub fn dasherize(word: &[u8]) -> Vec<u8> {
    word.iter()
        .map(|&b| if b == b'_' { b'-' } else { b })
        .collect()
}

/// Underscores become spaces and the first byte is upper cased. Nothing else is
/// touched — no `_id` stripping, no lower casing of the tail ("aB" -> "AB").
pub fn humanize(word: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = word
        .iter()
        .map(|&b| if b == b'_' { b' ' } else { b })
        .collect();
    if let Some(first) = out.first_mut() {
        *first = to_upper(*first);
    }
    out
}

/// Upper cases the byte that starts each space separated run and lower cases the
/// rest. Only U+0020 separates words, so "hello_world" -> "Hello_world" and
/// "HelloWorld" -> "Helloworld".
pub fn titleize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut capitalize_next = true;
    for &b in word {
        if b == b' ' {
            out.push(b);
            capitalize_next = true;
        } else if capitalize_next {
            out.push(to_upper(b));
            capitalize_next = false;
        } else {
            out.push(to_lower(b));
        }
    }
    out
}

/// Builds a URL-ish slug: alphanumerics are lower cased, spaces become dashes and
/// every other byte is dropped outright (underscores and existing dashes
/// included). Runs are *not* squeezed — "a  b" yields "a--b" — but leading and
/// trailing dashes are trimmed.
pub fn parameterize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for &b in word {
        if is_alnum(b) {
            out.push(to_lower(b));
        } else if b == b' ' {
            out.push(b'-');
        }
    }
    let start = out.iter().take_while(|&&b| b == b'-').count();
    let end = out.len() - out[start..].iter().rev().take_while(|&&b| b == b'-').count();
    out[start..end].to_vec()
}

/// The upper camel case singular form of a word.
pub fn classify(word: &[u8]) -> Vec<u8> {
    camelize_with(&singularize(word), false)
}

/// The plural, underscored table-style form of a word.
pub fn tableize(word: &[u8]) -> Vec<u8> {
    pluralize(&underscore(word))
}

/// `truncate(word, length)` with the default "..." omission marker.
pub fn truncate(word: &[u8], length: usize) -> Vec<u8> {
    truncate_with(word, length, b"...")
}

/// Shortens `word` to `length` bytes, spending the last bytes of the budget on
/// `omission`. The measurement is in bytes, exactly as `std::string::length`
/// counts, so a multi-byte UTF-8 sequence can be cut in half.
pub fn truncate_with(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
    if word.len() <= length {
        return word.to_vec();
    }
    let keep = length.saturating_sub(omission.len()).min(word.len());
    let mut out = word[..keep].to_vec();
    out.extend_from_slice(omission);
    out
}

/// Strips the namespace qualification from a name.
///
/// The C++ implementation looks for the last `:` byte and then skips two bytes,
/// which only lines up when the separator really is a trailing `"::"`. For
/// "Test::cat" that yields "at" rather than "cat", and when the last `:` is the
/// final byte the underlying `substr` runs past the end and throws
/// `std::out_of_range`, aborting the process.
pub fn demodulize(name: &[u8]) -> Vec<u8> {
    match name.iter().rposition(|&b| b == b':') {
        None => name.to_vec(),
        Some(pos) => {
            let start = pos + 2;
            if start > name.len() {
                substr_out_of_range(start, name.len());
            }
            name[start..].to_vec()
        }
    }
}

/// Reproduces the unhandled `std::out_of_range` escaping `main`: the same
/// message on stderr, nothing on stdout, and death by SIGABRT.
fn substr_out_of_range(pos: usize, size: usize) -> ! {
    eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
    eprintln!(
        "  what():  basic_string::substr: __pos (which is {}) > this->size() (which is {})",
        pos, size
    );
    std::process::abort()
}

/// Human readable ordinal for a number: 1 -> "1st", 12 -> "12th", 23 -> "23rd".
pub fn ordinalize(number: i64) -> Vec<u8> {
    let abs = number.unsigned_abs();
    let suffix = match (abs % 100, abs % 10) {
        (11..=13, _) => "th",
        (_, 1) => "st",
        (_, 2) => "nd",
        (_, 3) => "rd",
        _ => "th",
    };
    format!("{}{}", number, suffix).into_bytes()
}

/// Re-exported so that call sites reading like the C++ original keep working.
pub fn capitalize_word(word: &[u8]) -> Vec<u8> {
    capitalize(word)
}

