pub fn truncate(word: &[u8], length: usize) -> Vec<u8> {
    truncate_with(word, length, b"...")
}

/// Shortens `word` to `length` bytes, spending the last bytes of the budget on
/// `omission`. The measurement is in bytes, exactly as `std::string::length`
/// counts, so a multi-byte UTF-8 sequence can be cut in half.
pub fn truncate_with(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
    if word.len() <= length {
        return word.to_vec();
    }
    let keep = length.saturating_sub(omission.len()).min(word.len());
    let mut out = word[..keep].to_vec();
    out.extend_from_slice(omission);
    out
}

/// Strips the namespace qualification from a name.
///
/// The C++ implementation looks for the last `:` byte and then skips two bytes,
/// which only lines up when the separator really is a trailing `"::"`. For
/// "Test::cat" that yields "at" rather than "cat", and when the last `:` is the
/// final byte the underlying `substr` runs past the end and throws
/// `std::out_of_range`, aborting the process.
pub fn demodulize(name: &[u8]) -> Vec<u8> {
    match name.iter().rposition(|&b| b == b':') {
        None => name.to_vec(),
        Some(pos) => {
            let start = pos + 2;
            if start > name.len() {
                substr_out_of_range(start, name.len());
            }
            name[start..].to_vec()
        }
    }
}

/// Reproduces the unhandled `std::out_of_range` escaping `main`: the same
/// message on stderr, nothing on stdout, and death by SIGABRT.
fn substr_out_of_range(pos: usize, size: usize) -> ! {
    eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
    eprintln!(
        "  what():  basic_string::substr: __pos (which is {}) > this->size() (which is {})",
        pos, size
    );
    std::process::abort()
}

/// Human readable ordinal for a number: 1 -> "1st", 12 -> "12th", 23 -> "23rd".
pub fn ordinalize(number: i64) -> Vec<u8> {
    let abs = number.unsigned_abs();
    let suffix = match (abs % 100, abs % 10) {
        (11..=13, _) => "th",
        (_, 1) => "st",
        (_, 2) => "nd",
        (_, 3) => "rd",
        _ => "th",
    };
    format!("{}{}", number, suffix).into_bytes()
}

/// Re-exported so that call sites reading like the C++ original keep working.
pub fn capitalize_word(word: &[u8]) -> Vec<u8> {
    capitalize(word)
}

