//! A dependency-free Rust port of the `inflection` C++ library.
//!
//! # Why everything is bytes
//!
//! The original operates on `std::string`, which is a sequence of bytes with no
//! encoding attached, under the C locale. Several of its behaviours are only
//! observable at that level: `truncate` counts bytes and will happily cut a UTF-8
//! sequence in half, `demodulize` can return a lone continuation byte, and
//! `parameterize` discards every byte >= 0x80. So the whole library speaks
//! `&[u8]` -> `Vec<u8>` and the caller writes the raw bytes back out.

pub mod ascii;
pub mod case;
pub mod number;
pub mod transform;
pub mod uncountable;

/// The C++ `inflection::Inflector` class, whose members are all static.
pub struct Inflector;

impl Inflector {
    /// The C++ version fills in its rule tables here; the Rust rules are
    /// compile-time constants, so this exists purely to keep call sites aligned.
    pub fn initialize() {}

    pub fn pluralize(word: &[u8]) -> Vec<u8> {
        number::pluralize(word)
    }

    pub fn singularize(word: &[u8]) -> Vec<u8> {
        number::singularize(word)
    }

    /// `camelize(word)` — first byte left alone.
    pub fn camelize(word: &[u8]) -> Vec<u8> {
        transform::camelize(word)
    }

    /// `camelize(word, lower_first)` — the two argument overload.
    pub fn camelize_with(word: &[u8], lower_first: bool) -> Vec<u8> {
        transform::camelize_with(word, lower_first)
    }

    pub fn underscore(word: &[u8]) -> Vec<u8> {
        transform::underscore(word)
    }

    pub fn classify(word: &[u8]) -> Vec<u8> {
        transform::classify(word)
    }

    pub fn tableize(word: &[u8]) -> Vec<u8> {
        transform::tableize(word)
    }

    pub fn humanize(word: &[u8]) -> Vec<u8> {
        transform::humanize(word)
    }

    pub fn titleize(word: &[u8]) -> Vec<u8> {
        transform::titleize(word)
    }

    pub fn dasherize(word: &[u8]) -> Vec<u8> {
        transform::dasherize(word)
    }

    pub fn parameterize(word: &[u8]) -> Vec<u8> {
        transform::parameterize(word)
    }

    pub fn upcase(word: &[u8]) -> Vec<u8> {
        case::upcase(word)
    }

    pub fn downcase(word: &[u8]) -> Vec<u8> {
        case::downcase(word)
    }

    pub fn capitalize(word: &[u8]) -> Vec<u8> {
        case::capitalize(word)
    }

    pub fn decapitalize(word: &[u8]) -> Vec<u8> {
        case::decapitalize(word)
    }

    pub fn truncate(word: &[u8], length: usize) -> Vec<u8> {
        transform::truncate(word, length)
    }

    pub fn truncate_with(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
        transform::truncate_with(word, length, omission)
    }

    pub fn demodulize(name: &[u8]) -> Vec<u8> {
        transform::demodulize(name)
    }

    pub fn is_plural(word: &[u8]) -> bool {
        number::is_plural(word)
    }

    pub fn is_singular(word: &[u8]) -> bool {
        number::is_singular(word)
    }

    pub fn ordinalize(number: i64) -> Vec<u8> {
        transform::ordinalize(number)
    }
}

