// Port of tests/test20.cpp — 20 Inflector calls over a single word argument.
//
// The library is pulled in by path so this file builds either way:
//     rustc -O test20.rs -o test20
//     cargo build --release
#[path = "src/inflection/mod.rs"]
mod inflection;

use inflection::Inflector;
use std::io::Write;

/// `std::to_string(bool)` promotes to int, so it prints "0" or "1".
fn to_string_bool(value: bool) -> Vec<u8> {
    if value {
        b"1".to_vec()
    } else {
        b"0".to_vec()
    }
}

fn concat(parts: &[&[u8]]) -> Vec<u8> {
    let mut out = Vec::new();
    for part in parts {
        out.extend_from_slice(part);
    }
    out
}

fn main() {
    Inflector::initialize();

    // 20 API calls - the most complex test
    let args: Vec<String> = std::env::args().collect();
    let argc = args.len();
    let mut all_results: Vec<Vec<u8>> = Vec::new();

    // Collect every available conversion
    if argc > 1 {
        let base_word = args[1].as_bytes();

        // 1-5: basic conversions
        all_results.push(Inflector::pluralize(base_word));
        all_results.push(Inflector::singularize(base_word));
        all_results.push(Inflector::camelize(base_word));
        all_results.push(Inflector::camelize_with(base_word, false));
        all_results.push(Inflector::underscore(base_word));

        // 6-10: more conversions
        all_results.push(Inflector::classify(base_word));
        all_results.push(Inflector::tableize(base_word));
        all_results.push(Inflector::humanize(base_word));
        all_results.push(Inflector::titleize(base_word));
        all_results.push(Inflector::dasherize(base_word));

        // 11-15: parameterized and others
        all_results.push(Inflector::parameterize(base_word));
        all_results.push(Inflector::parameterize(&concat(&[
            b"A ",
            base_word,
            b" Test",
        ])));
        all_results.push(Inflector::upcase(base_word));
        all_results.push(Inflector::downcase(base_word));
        all_results.push(Inflector::capitalize(base_word));

        // 16-20: extra features
        all_results.push(Inflector::decapitalize(base_word));
        all_results.push(Inflector::truncate(base_word, 5));
        all_results.push(Inflector::demodulize(&concat(&[b"Test::", base_word])));
        all_results.push(to_string_bool(Inflector::is_plural(base_word)));
        all_results.push(to_string_bool(Inflector::is_singular(base_word)));
    }

    // Fall back to defaults when there were not enough arguments
    if all_results.len() < 20 && argc > 1 {
        // use ordinals
        let mut i = 1;
        while i <= 5 && all_results.len() < 20 {
            all_results.push(Inflector::ordinalize(i));
            i += 1;
        }
    }

    // Emit exactly 20 results
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for result in all_results.iter().take(20) {
        out.write_all(result).unwrap();
        out.write_all(b"\n").unwrap();
    }
}

