87	    if n >= 4 && ends_with(word, b"ves") && word[n - 4] != b'f' {
88	        return joined(&word[..n - 3], b"fe");
89	    }
90	
91	    // ([^aeiouy]|qu)ies$ -> \1y
92	    if n >= 4 && ends_with(word, b"ies") {
93	        let prev = word[n - 4];
94	        let qu = prev == b'u' && n >= 5 && word[n - 5] == b'q';
95	        if !is_vowel_or_y(prev) || qu {
96	            return joined(&word[..n - 3], b"y");
97	        }
98	    }
99	
100	    // (m|l)ice$ -> \1ouse   (not anchored: "slice" -> "slouse")
101	    if n >= 4 && ends_with(word, b"ice") && (word[n - 4] == b'm' || word[n - 4] == b'l') {
102	        return joined(&word[..n - 3], b"ouse");
103	    }
104	
105	    // (bus)es$ -> \1
106	    if ends_with(word, b"buses") {
107	        return head(word, n - 2);
108	    }
