122	    if ends_with(word, b"octopi") || ends_with(word, b"viri") {
123	        return joined(&word[..n - 1], b"us");
124	    }
125	
126	    // (alias|status)es$ -> \1
127	    if ends_with(word, b"aliases") || ends_with(word, b"statuses") {
128	        return head(word, n - 2);
129	    }
130	
131	    // ^(ox)en$ -> \1   (anchored at both ends: "oxens" and "moxen" are untouched)
132	    if word == b"oxen" {
