137	    if ends_with(word, b"vertices") || ends_with(word, b"indices") {
138	        return joined(&word[..n - 4], b"ex");
139	    }
140	
141	    // (matr)ices$ -> \1ix
142	    if ends_with(word, b"matrices") {
143	        return joined(&word[..n - 4], b"ix");
144	    }
145	
146	    // (quiz)zes$ -> \1
147	    if ends_with(word, b"quizzes") {
148	        return head(word, n - 3);
149	    }
150	
