168	/// A word counts as plural exactly when singularising it changes it. Uncountable
169	/// nouns and irregulars the rule list does not cover ("children", "men",
170	/// "people", "geese") therefore report as singular.
171	pub fn is_plural(word: &[u8]) -> bool {
172	    singularize(word) != word
173	}
174	
175	pub fn is_singular(word: &[u8]) -> bool {
176	    !is_plural(word)
177	}

