// Differential fuzzer: runs the C++ reference binary and the Rust port over a
// large generated corpus and compares stdout, stderr and exit status byte for byte.
//
//   rustc -O difftest.rs -o difftest && ./difftest [max_reports]

use std::process::Command;

const CPP: &str = "/workspace/dataset/test20_executable";
const RS: &str = "/output/test20";

// ---------------------------------------------------------------- corpus ----

const CURATED: &[&str] = &[
    "cat", "dogs", "person", "people", "child", "children", "bus", "buses", "boxes", "box", "city",
    "cities", "boy", "days", "knife", "knives", "wolves", "wolf", "mouse", "mice", "men", "man",
    "class", "glass", "glasses", "classes", "Class", "HelloWorld", "hello_world", "hello world",
    "Hello World", "ADMIN", "aB", "a-b", "a_b_c", "foo.bar", "Foo::Bar", "x", "ab", "abcde",
    "abcdef", "  spaced  ", "Ünï", "123", "a1b2", "series", "Series", "SERIES", "sheep", "fish",
    "Fish", "FISH", "goldfish", "my fish", "news", "NEWS", "newss", "enews", "views", "equipment",
    "information", "rice", "money", "species", "jeans", "police", "analyses", "Analyses",
    "ANALYSES", "banalyses", "xanalyses", "bases", "abases", "xabases", "diagnoses", "parentheses",
    "xtheses", "theses", "thebases", "anthebases", "prognoses", "synopses", "crises", "crisis",
    "axes", "Axes", "AXES", "taxes", "foxes", "boxes", "testes", "testis", "axis", "oases",
    "phases", "phrases", "roses", "noses", "poses", "doses", "uses", "fuses", "houses", "cases",
    "faces", "notes", "churches", "dishes", "quizzes", "quizes", "zzes", "izzes", "aquizzes",
    "heroes", "potatoes", "shoes", "toes", "hoes", "does", "ties", "lies", "pies", "movies",
    "matrices", "vertices", "indices", "devices", "ices", "aices", "xices", "aliases", "statuses",
    "alias", "status", "octopi", "octopus", "octopii", "xoctopi", "viri", "virus", "oxen", "oxens",
    "ox", "oxe", "moxen", "boxen", "slice", "police", "lice", "mices", "Mice", "data", "datum",
    "media", "medium", "tia", "area", "sofa", "natives", "hives", "lives", "aseries", "databases",
    "geese", "goose", "wolFves", "wolfves", "ies", "ves", "es", "s", "S", "as", "is", "us", "ss",
    "yses", "lyses", "alyses", "nalyses", "an alyses", "Xnalyses", "aalyses", "xses", "tses",
    "ases", "eses", "ises", "oses", "bses", "aies", "qies", "quies", "ques", "qus", "bies", "yies",
    "uies", "eies", "oies", "iies", "1ies", "-ies", "_ies", "ives", "fves", "afves", "ofves",
    "lves", "rves", "fes", "ches", "shes", "sses", "xes", "hes", "user_id", "id", "_id",
    "user_ids", "userid", "a__b", "_ab", "ab_", "__", "_", "a_b", "hello-world", "a\tb", "a 1b",
    "  a", "a  b", "a - b", "---", "  ", "a.b", "a\rb", "a\u{b}b", "a\u{c}b", "-a-", "9Z", "a:b",
    ":b", "a:b:c", "::x", "a::b", "A", "AB", "aBC", "A1B", "-A", "_A", "a\nb", "\n", "\t",
    "café", "naïve", "日本語", "ÜNÏ", "Ünïcodé", "ß", "İ", "μ", "€", "𝄞", "e\u{301}",
];

const SUFFIXES: &[&str] = &[
    "s", "es", "ies", "ves", "oes", "ses", "xes", "zes", "ches", "shes", "sses", "zzes", "ices",
    "en", "ice", "i", "a", "us", "is", "sis", "news", "ews", "quizzes", "buses", "axes", "testes",
    "crises", "aliases", "statuses", "vertices", "indices", "matrices", "octopi", "viri", "oxen",
    "analyses", "bases", "theses", "", "S", "ES", "_", "-", " ", ".", ":", "::",
];

const PREFIXES: &[&str] = &[
    "", "a", "b", "q", "x", "z", "f", "o", "m", "l", "t", "th", "qu", "an", "ba", "the", "analy",
    "parenthe", "progno", "synop", "diagno", "cris", "test", "ax", "bus", "matr", "vert", "ind",
    "alias", "status", "octop", "vir", "ox", "quiz", "A", "Z", "_", "-", " ", "Foo::", "hello_",
    "HelloW", "café",
];

/// Deterministic xorshift so runs are reproducible.
struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

const ALPHABET: &[&str] = &[
    "a", "b", "c", "d", "e", "f", "i", "l", "m", "o", "q", "r", "s", "t", "u", "v", "x", "y", "z",
    "A", "B", "S", "X", "Z", "0", "1", "9", "_", "-", " ", ".", ":", "\t", "\n", "é", "Ü", "日",
    "'", "\"", "/", "!", "~", "+", "=", "(", ")", "[", "]", "{", "}", "*", "&", "%", "$", "#", "@",
    "^", "|", "\\", "<", ">", "?", ",", ";", "`",
];

fn build_corpus() -> Vec<String> {
    let mut corpus: Vec<String> = Vec::new();
    corpus.extend(CURATED.iter().map(|s| s.to_string()));

    // Systematic prefix x suffix cross product exercises every rule boundary.
    for p in PREFIXES {
        for s in SUFFIXES {
            corpus.push(format!("{}{}", p, s));
            corpus.push(format!("{}{}", p.to_uppercase(), s));
            corpus.push(format!("{}{}", p, s.to_uppercase()));
        }
    }

    // Every 1- and 2-byte ASCII-letter word, plus all 3-letter words over a
    // reduced alphabet, so short-string edge cases are covered exhaustively.
    for a in b'a'..=b'z' {
        corpus.push((a as char).to_string());
        corpus.push((a as char).to_uppercase().to_string());
        for b in b'a'..=b'z' {
            corpus.push(format!("{}{}", a as char, b as char));
        }
    }
    let short = b"aeiouyqsxzchlmrvftn_- ";
    for &a in short {
        for &b in short {
            for &c in short {
                corpus.push(format!("{}{}{}", a as char, b as char, c as char));
            }
        }
    }

    // Random strings across a wide byte alphabet, lengths 0..24.
    let mut rng = Rng(0x2545F4914F6CDD1D);
    for _ in 0..30000 {
        let len = rng.below(25);
        let mut word = String::new();
        for _ in 0..len {
            word.push_str(ALPHABET[rng.below(ALPHABET.len())]);
        }
        corpus.push(word);
    }

    // A couple of long inputs.
    corpus.push("a".repeat(10000));
    corpus.push("Ab_".repeat(500));
    corpus.push("café ".repeat(300));

    corpus.sort();
    corpus.dedup();
    corpus
}

// ------------------------------------------------------------- comparison ----

fn run(bin: &str, word: &str) -> (Vec<u8>, Vec<u8>, Option<i32>) {
    let out = Command::new(bin)
        .arg(word)
        .output()
        .unwrap_or_else(|e| panic!("failed to run {}: {}", bin, e));
    (out.stdout, out.stderr, out.status.code())
}

fn show(bytes: &[u8]) -> String {
    let mut s = String::new();
    for &b in bytes {
        match b {
            b'\n' => s.push_str("\\n"),
            b'\t' => s.push_str("\\t"),
            b'\r' => s.push_str("\\r"),
            0x20..=0x7e => s.push(b as char),
            _ => s.push_str(&format!("\\x{:02x}", b)),
        }
    }
    s
}

fn main() {
    let max_reports: usize = std::env::args()
        .nth(1)
        .and_then(|a| a.parse().ok())
        .unwrap_or(25);

    let corpus = build_corpus();
    eprintln!("corpus: {} cases", corpus.len());

    let mut mismatches = 0usize;
    let mut aborts = 0usize;
    let mut reported = 0usize;

    for (i, word) in corpus.iter().enumerate() {
        if word.contains('\0') {
            continue;
        }
        let (cpp_out, _cpp_err, cpp_code) = run(CPP, word);
        let (rs_out, _rs_err, rs_code) = run(RS, word);

        let same_status = match (cpp_code, rs_code) {
            // Both died from a signal (SIGABRT surfaces as None from .code()).
            (None, None) => true,
            (a, b) => a == b,
        };
        if cpp_code.is_none() || cpp_code == Some(134) {
            aborts += 1;
        }

        if cpp_out != rs_out || !same_status {
            mismatches += 1;
            if reported < max_reports {
                reported += 1;
                println!("MISMATCH #{} case {} word=[{}]", mismatches, i, show(word.as_bytes()));
                let cpp_lines: Vec<&[u8]> = cpp_out.split(|&b| b == b'\n').collect();
                let rs_lines: Vec<&[u8]> = rs_out.split(|&b| b == b'\n').collect();
                if cpp_out.is_empty() != rs_out.is_empty() || cpp_lines.len() != rs_lines.len() {
                    println!("  cpp stdout=[{}] code={:?}", show(&cpp_out), cpp_code);
                    println!("  rs  stdout=[{}] code={:?}", show(&rs_out), rs_code);
                } else {
                    for (n, (c, r)) in cpp_lines.iter().zip(rs_lines.iter()).enumerate() {
                        if c != r {
                            println!("  line {}: cpp=[{}] rs=[{}]", n + 1, show(c), show(r));
                        }
                    }
                    if !same_status {
                        println!("  status: cpp={:?} rs={:?}", cpp_code, rs_code);
                    }
                }
            }
        }

        if i % 5000 == 0 && i > 0 {
            eprintln!("  {}/{} checked, {} mismatches", i, corpus.len(), mismatches);
        }
    }

    println!(
        "\n=== {} cases, {} abort-path cases, {} mismatches ===",
        corpus.len(),
        aborts,
        mismatches
    );
    if mismatches > 0 {
        std::process::exit(1);
    }
}

