    // The two are always exact opposites.
    for word in [&b"cat"[..], b"dogs", b"jeans", b"", b"s", b"Series"] {
        assert_ne!(Inflector::is_plural(word), Inflector::is_singular(word));
    }
}

#[test]
fn camelize_honours_the_lower_first_default() {
    assert_eq!(s(Inflector::camelize(b"hello_world")), "helloWorld");
    assert_eq!(s(Inflector::camelize_with(b"hello_world", false)), "HelloWorld");
    // The default overload leaves the first byte alone rather than lowering it.
    assert_eq!(s(Inflector::camelize(b"HelloWorld")), "HelloWorld");
    assert_eq!(s(Inflector::camelize(b"aB")), "aB");
    assert_eq!(s(Inflector::camelize_with(b"aB", false)), "AB");
    assert_eq!(s(Inflector::camelize(b"a_b_c")), "aBC");
    assert_eq!(s(Inflector::camelize(b"_id")), "Id");
    assert_eq!(s(Inflector::camelize(b"ab_")), "ab");
    assert_eq!(s(Inflector::camelize(b"__")), "");
    assert_eq!(s(Inflector::camelize_with(b"__", false)), "");
}

#[test]
fn underscore_splits_on_upper_case_only() {
    assert_eq!(s(Inflector::underscore(b"HelloWorld")), "hello_world");
    assert_eq!(s(Inflector::underscore(b"ADMIN")), "a_d_m_i_n");
    assert_eq!(s(Inflector::underscore(b"Hello World")), "hello _world");
    assert_eq!(s(Inflector::underscore(b"Foo::Bar")), "foo::_bar");
    // Dashes are not separators and are left untouched.
    assert_eq!(s(Inflector::underscore(b"a-b")), "a-b");
}

#[test]
fn classify_and_tableize_are_compositions() {
    assert_eq!(s(Inflector::classify(b"dogs")), "Dog");
    assert_eq!(s(Inflector::classify(b"hello_world")), "HelloWorld");
    assert_eq!(s(Inflector::classify(b"s")), "");
    assert_eq!(s(Inflector::tableize(b"HelloWorld")), "hello_worlds");
    assert_eq!(s(Inflector::tableize(b"ADMIN")), "a_d_m_i_ns");
    // tableize goes through pluralize, so the uncountable list still applies.
    assert_eq!(s(Inflector::tableize(b"Series")), "series");
}

#[test]
fn humanize_and_titleize_differ_in_their_separators() {
    assert_eq!(s(Inflector::humanize(b"hello_world")), "Hello world");
    assert_eq!(s(Inflector::humanize(b"user_id")), "User id"); // no _id stripping
    assert_eq!(s(Inflector::humanize(b"aB")), "AB"); // tail is untouched
    assert_eq!(s(Inflector::humanize(b"  spaced  ")), "  spaced  ");
    // titleize only ever breaks on a literal space.
    assert_eq!(s(Inflector::titleize(b"hello world")), "Hello World");
    assert_eq!(s(Inflector::titleize(b"hello_world")), "Hello_world");
    assert_eq!(s(Inflector::titleize(b"HelloWorld")), "Helloworld");
    assert_eq!(s(Inflector::titleize(b"  spaced  ")), "  Spaced  ");
    assert_eq!(s(Inflector::titleize(b"Foo::Bar")), "Foo::bar");
}

#[test]
fn parameterize_drops_punctuation_and_trims_dashes() {
    assert_eq!(s(Inflector::parameterize(b"Hello World")), "hello-world");
    // Underscores and dashes are removed outright, not turned into separators.
    assert_eq!(s(Inflector::parameterize(b"hello_world")), "helloworld");
    assert_eq!(s(Inflector::parameterize(b"a-b")), "ab");
    assert_eq!(s(Inflector::parameterize(b"Foo::Bar")), "foobar");
    // Only U+0020 becomes a dash; other whitespace disappears.
    assert_eq!(s(Inflector::parameterize(b"a\tb")), "ab");
    // Runs are preserved, the ends are trimmed.
    assert_eq!(s(Inflector::parameterize(b"a  b")), "a--b");
    assert_eq!(s(Inflector::parameterize(b"  spaced  ")), "spaced");
    assert_eq!(s(Inflector::parameterize(b"A   spaced   Test")), "a---spaced---test");
    assert_eq!(s(Inflector::parameterize(b"---")), "");
    // Bytes >= 0x80 are not alphanumeric in the C locale.
    assert_eq!(s(Inflector::parameterize("Ünï".as_bytes())), "n");
}

#[test]
fn case_helpers_stay_ascii_only() {
    assert_eq!(s(Inflector::upcase(b"cat")), "CAT");
    assert_eq!(s(Inflector::downcase(b"ADMIN")), "admin");
    assert_eq!(s(Inflector::capitalize(b"ADMIN")), "Admin");
    assert_eq!(s(Inflector::capitalize(b"  spaced  ")), "  spaced  ");
    assert_eq!(s(Inflector::decapitalize(b"ADMIN")), "aDMIN");
    assert_eq!(s(Inflector::decapitalize(b"HelloWorld")), "helloWorld");
    // The non-ASCII bytes of "Ünï" survive upcase untouched.
    assert_eq!(Inflector::upcase("Ünï".as_bytes()), "ÜNï".as_bytes());
}

#[test]
fn truncate_counts_bytes() {
    assert_eq!(s(Inflector::truncate(b"cat", 5)), "cat");
    assert_eq!(s(Inflector::truncate(b"abcde", 5)), "abcde");
    assert_eq!(s(Inflector::truncate(b"abcdef", 5)), "ab...");
    assert_eq!(s(Inflector::truncate(b"person", 5)), "pe...");
    // "Ünï" is five bytes, so it fits even though it is three characters.
    assert_eq!(Inflector::truncate("Ünï".as_bytes(), 5), "Ünï".as_bytes());
    // Six bytes do not fit, and the cut lands inside a UTF-8 sequence.
    assert_eq!(Inflector::truncate("ééé".as_bytes(), 5), b"\xc3\xa9...");
}

#[test]
fn demodulize_skips_two_bytes_past_the_last_colon() {
    // The off-by-one is the documented behaviour, not a port mistake.
    assert_eq!(s(Inflector::demodulize(b"Test::cat")), "at");
    assert_eq!(s(Inflector::demodulize(b"Test::x")), "");
    assert_eq!(s(Inflector::demodulize(b"Test::Foo::Bar")), "ar");
    // A single colon inside the name moves the split point.
    assert_eq!(s(Inflector::demodulize(b"Test::a:b")), "");
    assert_eq!(s(Inflector::demodulize(b"nocolon")), "nocolon");
}

#[test]
fn ordinalize_covers_the_teens() {
    assert_eq!(s(Inflector::ordinalize(1)), "1st");
    assert_eq!(s(Inflector::ordinalize(2)), "2nd");
    assert_eq!(s(Inflector::ordinalize(3)), "3rd");
    assert_eq!(s(Inflector::ordinalize(4)), "4th");
    assert_eq!(s(Inflector::ordinalize(11)), "11th");
    assert_eq!(s(Inflector::ordinalize(12)), "12th");
    assert_eq!(s(Inflector::ordinalize(13)), "13th");
    assert_eq!(s(Inflector::ordinalize(21)), "21st");
    assert_eq!(s(Inflector::ordinalize(112)), "112th");
}
